procedure PhysioSOP {
  about "Send reminders for sessions that are booked or reminded."
  policy PhysioPolicy
  sheet Sessions "Sessions" { patient: Text, mobile: Phone, session_at: DateTime, therapist: Text, status: Text, injury: Text private }

  let today = date_of(now())
  let messages = []

  for each r in Sessions where r.session_at == today and (r.status == "booked" or r.status == "reminded") {
    let msg = ""
    if r.patient != "" {
      msg += r.patient + ", "
    } else {
      msg += "there, "
