    if r.injury != "" {
      msg += "You have an injury. "
    }
    msg = msg.trim()
    messages.append(msg)
  }

  let num_messages = length(messages)

  if num_messages > 40 {
    notify owner "Too many messages sent today. Please check your schedule."
    stop "Too many messages sent today. Please check your schedule."
