procedure Reminder {
  about "Remind learners to bring their licenses before tests."
  policy DrivingPolicy
  sheet Learners "Learners" { learner: Text, phone: Phone, lessons_left: Number, test_date: Date, status: Text, license_no: Text private }

  let today = today()
  let start_date = date_of(today - 7 days)
  let end_date = date_of(today)

  let learners = filter Learners where status == "active" and lessons_left > 0 and test_date >= start_date and test_date <= end_date

  for each learner in learners up to 15 {
