  let start_date = date_of(today) - 31 days
  let learners_passed = filter Learners where status == "passed" and test_date >= start_date

  let stats_row = { day: today, passed: count learners_passed }
  append Stats stats_row

  notify owner "Number of learners passed in the last 31 days: {stats_row.passed}"
