procedure RewardLoyaltyMembers {
  about "Reward loyalty members based on their stamps."
  policy CoffeePolicy
  sheet LoyaltyMembers "LoyaltyMembers" { name: Text, email: Email, stamps: Number, last_visit: Date, status: Text }

  let today = today()
  let tomorrow = today() + 1 day
  let one_hour_ago = today() - 1 hour
