procedure NewReturn {
  about "Handle a new return in the Returns sheet."
  policy HardwarePolicy
  sheet Returns "Returns" { return_no: Text, customer: Text, phone: Phone, amount: Money, bought: Date, opened: Bool, status: Text }

  let r = fetch Returns
  let age = days_between(r.bought, today())
  let amount = r.amount

  if r.opened then {
    notify owner "The return has been opened. Please do not send a refund."
    stop
  }

  if age > 30 then {
    notify owner "The return is more than 30 days old. Please do not send a refund."
    stop
  }

  if amount > $100 then {
    notify owner "The return is over $100. You will handle it yourself."
    stop
