  let msg = draft sms to r.customer: "Dear {r.customer default 'there'},\n\nYour return has been processed.\n\nPlease let us know if there is anything we can help with."
  let ok = request approval of msg from owner timeout 6 hours else skip

  if ok then {
    send ok
    update r set status = "refunded"
    notify owner "Thank you for your cooperation."
  } else {
    notify owner "Your refund request was denied. Please try again later."
  }
}
