  about "Order shingles based on stock and policy."
  policy RoofPolicy
  sheet Materials "Materials" { material: Text, on_hand: Number, unit_cost: Money }

  let current_date = today()
  let threshold = 20
  let target_order = 50
  let bundle_price = 100  # Example bundle price

  let current_stock = sum on_hand of Materials
  let orders_needed = max(target_order - current_stock, 0)

  if orders_needed > 0 {
    let order_request = draft order "Shingles" from supplier "Acme Supply" quantity orders_needed at price bundle_price
    let approval = request approval of order_request from owner timeout 6 hours else skip

