procedure HandleRefundRequest {
  about "Handles refund requests according to the PlumbingRefundPolicy."

  policy PlumbingRefundPolicy

  sheet RefundRequests "RefundRequests" { request_id: Text, customer: Text, phone: Phone, amount: Money, purchased: Date, status: Text }

  statements...

  // Check if the purchase was more than 14 days ago
  let purchase_date = get RefundRequests.purchased
  let days_since_purchase = days_between(purchase_date, today())
  if days_since_purchase > 14 {
    let owner_message = "The purchase was more than 14 days ago. Please contact the owner."
    notify owner owner_message
    stop
  }

  // Check if the refund amount exceeds the limit
  let refund_amount = get RefundRequests.amount
  if refund_amount > $75 {
    let owner_message = "The refund amount exceeds $75. Please contact the owner."
    notify owner owner_message
    stop
  }

  // Check if the refund amount is less than or equal to the limit
  if refund_amount <= $15 {
    let owner_message = "The refund amount is less than or equal to $15. You can handle it yourself."
    notify owner owner_message
    update RefundRequests.status to "handled"
    notify customer "Your refund has been handled."
  } else {
    let owner_message = "The refund amount is greater than $15. Please contact the owner."
    notify owner owner_message
    let approval = request approval of owner timeout 6 hours else skip
    if approval {
      update RefundRequests.status to "approved"
      notify customer "Your refund has been approved."
    } else {
      notify customer "Your refund has not been approved."
    }
  }
}
