calculate_new_time(date) {
  let current_time = time_of(today())
  let diff_hours = (current_time.hour - date.hour) * 60 + (current_time.minute - date.minute)
  let new_hour = date.hour + diff_hours / 60
  let new_minute = date.minute + diff_hours % 60
  return date_of(today()) + duration(new_hour, new_minute)
}
