  let current_date = today()
  let days_since_purchase = days_between(purchase_date, current_date)

  if days_since_purchase > 60 {
    let owner_email = get RefundRequests.email
    let reason = "Purchase more than 60 days ago."
    notify owner_email reason stop
    return
  }

  // Check if the refund amount exceeds the limit
  let refund_amount = get RefundRequests.amount
  if refund_amount > $75 {
    let owner_email = get RefundRequests.email
    let reason = "Refund amount exceeds $75."
    notify owner_email reason stop
    return
  }

  // Check if the refund amount is less than or equal to the limit
