      notify owner "Daily order limit exceeded for {flower_name}. Please reduce the order size."
      skip
    }

    // Check if the order exceeds the monthly limit
    let last_order_date = get_last_order_date(flower_name)
    let days_since_last_order = days_between(last_order_date, today)
    if days_since_last_order >= 30 {
      notify owner "Monthly order limit exceeded for {flower_name}. Please reduce the order size."
      skip
    }

    // Ask for approval
    let approval = request approval of "Order {flower_name} from {flower_grower}?" from owner timeout 4 hours else skip

    // If approved, proceed with the order
    if approval {
      let order_id = order "Flowers" from flower_grower cost flower_reorder_qty * flower_unit_cost, ask owner first timeout 4 hours else skip
      send approval
    } else {
      notify owner "Order for {flower_name} from {flower_grower} denied. Please try again later."
      skip
    }
  }
}

// Helper function to get the last order date for a flower
function get_last_order_date(flower_name) {
  let last_order = filter Orders where flower = flower_name and status = "completed"
  if last_order.isEmpty() {
    return null
  } else {
    return last_order[0].date
  }
}

