procedure SOPPhotostudioPolicy {
  about "SOP for Photostudio Policy"

  policy PhotostudioPolicy {
    allow read Shoots(client, email, shoot_on, status, venue_notes)
    allow write Shoots(status)
    allow contact Shoots.email
    deny reveal Shoots.venue_notes
    limit sends 50 per day
    send only between 08:00 and 20:00
  }

  sheet Shoots "Shoots" { client: Text, email: Email, shoot_on: Date, status: Text, deposit: Money, venue_notes: Text private }

  trigger every monday at 08:30
  statements...

  let t = fetch Shoots
  let t2 = filter t where status == "delivered" and date_of(shoot_on) >= today() - 3 days
  let n = summarize count of t2

  if n == 0 {
    stop "No clients delivered in the last 3 days"
  } else {
    for each r in t2 up to n {
      let msg = draft sms to r.email subject "New Shoot Time Offer":
        "Hello {r.client},\n\nWe noticed that your shoot on {date_of(r.shoot_on)} was marked as 'delivered' in the last 3 days.\n\nWe would like to offer you a new time slot for your shoot.\n\nPlease let us know if you are interested in this opportunity.\n\nBest regards,\nThe Photostudio Team"
      let ok = request approval of msg from owner timeout 6 hours else skip
      send ok
      update r set status = "followed-up"
      append Shoots { client: r.client, email: r.email, shoot_on: r.shoot_on, status: "followed-up", deposit: r.deposit, venue_notes: r.venue_notes }
    }
  }
}

