  let today = today()
  let cutoff_date = date_of(today) - 5 days
  let filtered_pets = filter Pets where balance > 0 and vaccine_due > cutoff_date

  for each p in filtered_pets up to 40 {
    let reminder_text = "Dear {p.owner},\n\nYour pet's last vaccination was due {date_of(p.vaccine_due)}.\nPlease make sure to schedule a visit soon to keep your pet healthy.\n\nBest regards,\nThe Vet Team"
    let reminder = draft sms to p.phone: reminder_text
    let ok = request approval of reminder from owner timeout 6 hours else skip
    send ok
  }
}
